def main() -> int:
    write_jsonl(SOURCES / "curated" / "core.jsonl", S_)
    provs = [{"id": k, "name": v[0], "url": v[1], "authority": v[2], "terms_status": v[3], "terms_note": v[4],
              "terms_url": v[5]} for k, v in PROV.items()]
    write_jsonl(SOURCES.parent / "providers" / "providers.jsonl", provs)
    print(f"curated core: {len(S_)} sources, {len(provs)} providers")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
